  sub:pv-cut a schema:PropertyValue ;
    schema:propertyID "plausibilityCut" ;
    schema:value 0.5 ;
    schema:description "Plausibility score cut used for both real organisms and negatives (SCORER-EVALUATION.md:45, :46)." .

  sub:pv-neg-low a schema:PropertyValue ;
    schema:propertyID "negativesBelowCutLowestPercent" ;
    schema:value 12 ;
    schema:description "Lowest percentage of negatives scoring below the cut (SCORER-EVALUATION.md:46)." .

  sub:pv-neg-high a schema:PropertyValue ;
    schema:propertyID "negativesBelowCutHighestPercent" ;
    schema:value 17 ;
    schema:description "Highest percentage of negatives scoring below the cut (SCORER-EVALUATION.md:46)." .

  sub:pv-threshold a schema:PropertyValue ;
    schema:propertyID "familyPlausibleShareThresholdPercent" ;
    schema:value 80 ;
    schema:description "Share of a family's real items scoring plausible below which a family is listed as low (SCORER-EVALUATION.md:183)." .

  sub:pv-minimum-items a schema:PropertyValue ;
    schema:propertyID "minimumRealItemsPerListedFamily" ;
    schema:value 3 ;
    schema:description "Minimum number of real items a family needs to be listed in the low-family check (SCORER-EVALUATION.md:183)." .

  sub:pv-eury a schema:PropertyValue ;
    schema:propertyID "eurypharyngidaePlausibleCount" ;
    schema:value 3 ;
    schema:description "Gulper eels (Eurypharyngidae) scoring plausible: 3 of 5 (SCORER-EVALUATION.md:183)." .

  sub:pv-eury-total a schema:PropertyValue ;
    schema:propertyID "eurypharyngidaeRealItemCount" ;
    schema:value 5 ;
    schema:description "Real items in Eurypharyngidae (SCORER-EVALUATION.md:183)." .

  sub:pv-aspred a schema:PropertyValue ;
    schema:propertyID "aspredinidaePlausibleCount" ;
    schema:value 20 ;
    schema:description "Banjo catfishes (Aspredinidae) scoring plausible: 20 of 29 (SCORER-EVALUATION.md:183)." .

  sub:pv-aspred-total a schema:PropertyValue ;
    schema:propertyID "aspredinidaeRealItemCount" ;
    schema:value 29 ;
    schema:description "Real items in Aspredinidae (SCORER-EVALUATION.md:183)." .

  sub:pv-score a schema:PropertyValue ;
    schema:propertyID "fs-05942Score" ;
    schema:value 0.15 ;
    schema:description "Plausibility score of the gulper eel fs-05942, an example low scorer (SCORER-EVALUATION.md:186)." .

  sub:pv-distance a schema:PropertyValue ;
    schema:propertyID "fs-05942NearestNeighbourDistance" ;
    schema:value 0.96 ;
    schema:description "Distance from fs-05942 to its nearest remaining neighbour, the cutlassfish Lepturacanthus savala, once its family is removed (SCORER-EVALUATION.md:186)." .
}

